        if run_root_m: info['run_root_dir'] = run_root_m.group(1)

    # Get metrics from results/metrics
    metrics = exp.get('results', exp.get('metrics', {}))
    if isinstance(metrics, dict):
        info['metrics'] = metrics

    return info

